import{_ as a,c as o,o as r,ag as e}from"./chunks/framework.DyWQe55L.js";const i="/aiot-docs/assets/image-11.BQ6pJ3Ib.png",l="/aiot-docs/assets/image-12.W4cXl8WF.png",s="/aiot-docs/assets/image-13.fMyu562v.png",b=JSON.parse('{"title":"产品的定义","description":"","frontmatter":{},"headers":[],"relativePath":"operation-doc2.md","filePath":"operation-doc2.md"}'),n={name:"operation-doc2.md"};function d(h,t,c,g,p,u){return r(),o("div",null,t[0]||(t[0]=[e('<h1 id="产品的定义" tabindex="-1">产品的定义 <a class="header-anchor" href="#产品的定义" aria-label="Permalink to &quot;产品的定义&quot;">​</a></h1><p>在 IoT 平台中，<strong>产品（Product）</strong> 是一个非常核心的概念，定义清楚它能让后续的设备管理、物模型配置、消息通信都更加有条理。</p><hr><h2 id="_1-产品的定义" tabindex="-1">1. 产品的定义 <a class="header-anchor" href="#_1-产品的定义" aria-label="Permalink to &quot;1. 产品的定义&quot;">​</a></h2><p><strong>产品</strong> 是 <strong>同类设备的抽象模型</strong>，它是设备的模板，描述了一类设备的共同特征，比如：</p><ul><li>功能定义（物模型）</li><li>通信协议</li><li>数据格式</li><li>安全认证方式</li></ul><p>在实际系统中：</p><ul><li><strong>一个产品</strong> = <strong>一类设备的定义</strong></li><li><strong>一个设备</strong> = <strong>该产品的一个实例</strong></li></ul><p>例如：</p><ul><li>产品：智能温湿度传感器</li><li>设备：温湿度传感器 A、温湿度传感器 B</li></ul><hr><h2 id="_2-产品的核心要素" tabindex="-1">2. 产品的核心要素 <a class="header-anchor" href="#_2-产品的核心要素" aria-label="Permalink to &quot;2. 产品的核心要素&quot;">​</a></h2><h3 id="_2-1-产品基本信息" tabindex="-1">2.1 产品基本信息 <a class="header-anchor" href="#_2-1-产品基本信息" aria-label="Permalink to &quot;2.1 产品基本信息&quot;">​</a></h3><ul><li><strong>产品ID</strong>：平台自动生成，唯一标识</li><li><strong>产品名称</strong>：自定义，如“智能门锁”</li><li><strong>产品类型</strong>：设备分类，如传感器、网关、执行器</li><li><strong>通信协议</strong>：MQTT、CoAP、Modbus、HTTP等</li><li><strong>数据格式</strong>：JSON、二进制等</li></ul><hr><h3 id="_2-2-物模型" tabindex="-1">2.2 物模型 <a class="header-anchor" href="#_2-2-物模型" aria-label="Permalink to &quot;2.2 物模型&quot;">​</a></h3><p>每个产品对应一个物模型，定义这类设备的属性、服务、事件。</p><hr><h3 id="_2-3-安全认证" tabindex="-1">2.3 安全认证 <a class="header-anchor" href="#_2-3-安全认证" aria-label="Permalink to &quot;2.3 安全认证&quot;">​</a></h3><ul><li>每个产品可配置认证方式，如 <strong>设备密钥</strong>、<strong>X.509证书</strong></li><li>每个设备会在产品下分配唯一的 <strong>DeviceKey</strong> 和 <strong>Secret</strong></li></ul><hr><h3 id="_2-4-topic-规范" tabindex="-1">2.4 Topic 规范 <a class="header-anchor" href="#_2-4-topic-规范" aria-label="Permalink to &quot;2.4 Topic 规范&quot;">​</a></h3><p>通常会为产品定义标准的 MQTT Topic 模板：</p><ul><li>上报数据：<code>/{productId}/{deviceId}/pub</code></li><li>接收命令：<code>/{productId}/{deviceId}/sub</code></li></ul><p>这样所有设备都能基于统一的 Topic 模板进行通信。</p><hr><h2 id="_3-产品与设备的关系" tabindex="-1">3. 产品与设备的关系 <a class="header-anchor" href="#_3-产品与设备的关系" aria-label="Permalink to &quot;3. 产品与设备的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td>产品</td><td>一类设备的定义</td><td>智能温湿度传感器</td></tr><tr><td>设备</td><td>产品的一个实例</td><td>温湿度传感器 SN123456</td></tr><tr><td>物模型</td><td>描述设备的功能、数据格式和事件</td><td>温度属性、湿度属性等</td></tr><tr><td>Topic</td><td>设备通信的通道</td><td><code>/1/123456/sub</code></td></tr></tbody></table><hr><h2 id="_4-产品的生命周期" tabindex="-1">4. 产品的生命周期 <a class="header-anchor" href="#_4-产品的生命周期" aria-label="Permalink to &quot;4. 产品的生命周期&quot;">​</a></h2><ol><li><strong>创建产品</strong>：定义产品信息、物模型、认证方式</li><li><strong>创建设备</strong>：基于产品生成设备实例</li><li><strong>设备接入</strong>：设备使用分配的密钥连接到 IoT 平台</li><li><strong>数据通信</strong>：设备和平台按照产品定义的 Topic 通信</li><li><strong>设备管理</strong>：平台统一管理设备状态、数据</li></ol><h1 id="创建产品" tabindex="-1">创建产品 <a class="header-anchor" href="#创建产品" aria-label="Permalink to &quot;创建产品&quot;">​</a></h1><h2 id="_1-创建产品分类" tabindex="-1">1. 创建产品分类 <a class="header-anchor" href="#_1-创建产品分类" aria-label="Permalink to &quot;1. 创建产品分类&quot;">​</a></h2><p><img src="'+i+'" alt="alt text"></p><h2 id="_2-创建产品" tabindex="-1">2. 创建产品 <a class="header-anchor" href="#_2-创建产品" aria-label="Permalink to &quot;2. 创建产品&quot;">​</a></h2><p><img src="'+l+'" alt="alt text"></p><h2 id="_3-创建或导入物模型" tabindex="-1">3. 创建或导入物模型 <a class="header-anchor" href="#_3-创建或导入物模型" aria-label="Permalink to &quot;3. 创建或导入物模型&quot;">​</a></h2><p><img src="'+s+'" alt="alt text"></p>',38)]))}const m=a(n,[["render",d]]);export{b as __pageData,m as default};
